}

void DG_Init()
{
    if (GrOpen() < 0)
    {
        GrError("GrOpen failed");
        return;
    }

    gc = GrNewGC();
    GrSetGCUseBackground(gc, GR_FALSE);
    GrSetGCForeground(gc, MWRGB( 255, 0, 0 ));

    wid = GrNewBufferedWindow(GR_WM_PROPS_APPFRAME |
                        GR_WM_PROPS_CAPTION  |
                        GR_WM_PROPS_CLOSEBOX |
